def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    danger_count = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                danger_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev['bid']))
                except Exception:
                    pass

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    if supply <= 16:
        scarcity = 'tight'
    elif supply >= 22:
        scarcity = 'loose'
    else:
        scarcity = 'normal'

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if scarcity == 'tight':
        urgency += 2
    elif scarcity == 'normal':
        urgency += 1

    if day >= 8:
        urgency += 1

    if highest_prev >= 150:
        pressure = 'extreme'
    elif highest_prev >= 90:
        pressure = 'high'
    elif highest_prev >= 40:
        pressure = 'medium'
    else:
        pressure = 'low'

    if urgency >= 6:
        base = 120.0
        if pressure == 'extreme':
            bid = max(base, highest_prev + 3.0)
        elif pressure == 'high':
            bid = max(base - 10.0, highest_prev + 2.0)
        else:
            bid = base
    elif urgency >= 4:
        if scarcity == 'tight':
            base = 78.0
        elif scarcity == 'normal':
            base = 60.0
        else:
            base = 42.0

        if pressure == 'extreme':
            bid = min(base, 55.0)
        elif pressure == 'high':
            bid = max(base, min(highest_prev + 1.5, 88.0))
        elif pressure == 'medium':
            bid = max(base, avg_prev + 2.0)
        else:
            bid = base
    else:
        if scarcity == 'loose':
            base = 18.0
        elif scarcity == 'normal':
            base = 26.0
        else:
            base = 38.0

        if pressure == 'extreme':
            bid = 16.0
        elif pressure == 'high':
            bid = min(base, 24.0)
        elif pressure == 'medium':
            bid = min(max(base, avg_prev * 0.75), 34.0)
        else:
            bid = base

    if danger_count >= 2 and urgency <= 3:
        bid *= 0.9

    reserve_target = 0.0
    days_left = max(0, 10 - day)
    if hp > 4 and days_left > 0:
        reserve_target = min(140.0, days_left * 8.0)

    affordable = max(0.0, budget - reserve_target)
    if urgency >= 5:
        affordable = budget

    bid = min(bid, affordable if affordable > 0 else budget)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, 95.0))

    if bid < 0:
        bid = 0.0

    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o is not None and o.get('alive', False):
            alive_opponents.append(o)

    if not alive_opponents:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Infer pressure from yesterday's bids (only immediate reaction)
    yesterday_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    # If someone already bid very high yesterday, assume they may continue under threat.
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.85

    # Supply factor: with higher supply, we can bid slightly less and still secure water.
    # Avoid list indexing; just use thresholds.
    if supply <= MIN_SUPPLY + 0.5:
        supply_factor = 1.0
    elif supply >= MAX_SUPPLY - 0.5:
        supply_factor = 0.85
    else:
        supply_factor = 0.95

    # HP urgency: low HP => bid aggressively.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        base = DAILY_SALARY * (0.95 if high_pressure else 0.75)
    elif my_hp <= 5.0:
        base = DAILY_SALARY * (0.75 if high_pressure else 0.60)
    else:
        # Comfortable HP: bid to contest if opponent pressure is high.
        base = DAILY_SALARY * (0.65 if high_pressure else 0.50)

    # If yesterday highest bid was moderate, try to slightly overcut it when possible.
    # (We can't see today's bids, so this is a hedge.)
    target = max(base * supply_factor, min(my_budget, highest_prev_bid * 1.02))

    # Never exceed budget.
    bid = min(my_budget, target)

    # Keep a small floor so we don't get stuck at zero when contesting.
    # If budget is tiny, respect it.
    min_bid = min(my_budget, DAILY_SALARY * 0.15)
    if bid < min_bid:
        bid = min_bid

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0
    return float(bid)

